SCORE = {i: 0 for i in range(16)}


def signal_time_shift(signa1: np.ndarray, signal2: np.ndarray, unit: str = "s", rate: int = None) -> int | float:
    """
    Determine the time shift between the first and the second signal using cross-correlation.
    It can retour the result in second (unit='s') or in list index (unit='index')
    combien de temps d'avance à le signal 1 sur le signal 2
    """

    corr: np.ndarray = correlate(signa1, signal2, method="fft", mode="full")
    n = len(corr)

    if unit == "index":
        return floor(float(np.argmax(corr)) - n / 2)

    elif unit == "s":
        return (float(np.argmax(corr)) - n / 2) * (1 / rate)

    else:
        raise Exception("Unsupported unit.")


def labels_barycenter(coordinates: np.ndarray, labels: np.ndarray) -> dict:
    """
    This function calculate the barycenter of a labeled dataset.
    :param coordinates: Coordinates of points.
    :param labels: Labels of points.
    :return: Dict of the form : Label -> Barycenter
    """
    label_groups = {}

    for coord, label in zip(coordinates, labels):
        if label not in label_groups:
            label_groups[label] = []
        label_groups[label].append(coord)

    bc = {label: np.mean(coords, axis=0) for label, coords in label_groups.items()}

    return bc


def trilateration(center_mic: tuple,
                  mic1: tuple,
                  mic2: tuple,
                  distance_shift_c1: float,
                  distance_shift_c2: float) -> tuple[float, float]:
    """
    This function uses trilateration equations to find the coordinate of a point based on latency with microphones.
    :param center_mic: Center point of the trilateration. (microphone 0)
    :param mic1: microphone 1 used to trialterate
    :param mic2: microphone 2 used to trilaterate
    :param distance_shift_c1: "distance shift" between m0 and m1
    :param distance_shift_c2: "distance shift" between m0 and m2
    :return: The coordinate of the source. Exception if it had not been found.
    """
    x1, y1 = (mic1[0] - center_mic[0], mic1[1] - center_mic[1])
    x2, y2 = (mic2[0] - center_mic[0], mic2[1] - center_mic[1])
    t1 = distance_shift_c1
    t2 = distance_shift_c2

    candidates = set()

    y_candidate = [
        lambda x: (-t1 * sqrt(
            (-t1 ** 2 + x1 ** 2 + y1 ** 2) * (-t1 ** 2 + 4 * x ** 2 - 4 * x * x1 + x1 ** 2 + y1 ** 2)) * (
                           t1 - y1) * (t1 + y1) + y1 * (t1 ** 2 - y1 ** 2) * (
                           t1 ** 2 + 2 * x * x1 - x1 ** 2 - y1 ** 2)) / (
                          2 * (t1 - y1) * (t1 + y1) * (t1 ** 2 - y1 ** 2)),
        lambda x: (t1 * sqrt(
            (-t1 ** 2 + x1 ** 2 + y1 ** 2) * (-t1 ** 2 + 4 * x ** 2 - 4 * x * x1 + x1 ** 2 + y1 ** 2)) * (
                           t1 - y1) * (t1 + y1) + y1 * (t1 ** 2 - y1 ** 2) * (
                           t1 ** 2 + 2 * x * x1 - x1 ** 2 - y1 ** 2)) / (
                          2 * (t1 - y1) * (t1 + y1) * (t1 ** 2 - y1 ** 2)),
        lambda x: (-t2 * sqrt(
            (-t2 ** 2 + x2 ** 2 + y2 ** 2) * (-t2 ** 2 + 4 * x ** 2 - 4 * x * x2 + x2 ** 2 + y2 ** 2)) * (
                           t2 - y2) * (t2 + y2) + y2 * (t2 ** 2 - y2 ** 2) * (
                           t2 ** 2 + 2 * x * x2 - x2 ** 2 - y2 ** 2)) / (
                          2 * (t2 - y2) * (t2 + y2) * (t2 ** 2 - y2 ** 2)),
        lambda x: (t2 * sqrt(
            (-t2 ** 2 + x2 ** 2 + y2 ** 2) * (-t2 ** 2 + 4 * x ** 2 - 4 * x * x2 + x2 ** 2 + y2 ** 2)) * (
                           t2 - y2) * (t2 + y2) + y2 * (t2 ** 2 - y2 ** 2) * (
                           t2 ** 2 + 2 * x * x2 - x2 ** 2 - y2 ** 2)) / (
                          2 * (t2 - y2) * (t2 + y2) * (t2 ** 2 - y2 ** 2)),

    ]

    for fy in y_candidate:
        for fx in x_candidate:
            try:
                x = fx(x1, x2, y1, y2, t1, t2)
                candidate = (x + center_mic[0], fy(x) + center_mic[1])

                candidates.add(candidate)
            except Exception as e:
                _ = e

    def candidate_compare(cand):
        """
        Function to compare many candidates
        :param cand: candidate
        :return: The error on this candidate
        """
        cand = cand[:2]
        cd1 = abs(euclidian_distance(*center_mic, 0, *cand, 0) - euclidian_distance(*mic1, 0, *cand, 0) - t1)
        cd2 = abs(euclidian_distance(*center_mic, 0, *cand, 0) - euclidian_distance(*mic2, 0, *cand, 0) - t2)
        return cd1 + cd2

    c = min(candidates, key=candidate_compare, default=None)

    return c


def possible_coordinate(microphones: list[Microphone],
                        distance_shift: list[tuple | list],
                        start_point: np.ndarray | None,
                        max_error: float,
                        method: str = "optimize"
                        ) -> list[tuple[float, float, float]]:
    """
    Find many possible coordinate for a set of candidate.
    :param microphones: List of microhpones used.
    :param distance_shift: List of mesured "distance shift" in records
    :param start_point: The starting point of the search
    :param max_error: The max tolarated error in m
    :param method: Methode to use ('optimize' or 'trilateration')
    :return:
    """
    # Create the error function
    n = len(distance_shift[0])
    dim = len(start_point)

    t_range = [(i, j) for j in range(n) for i in range(n) if j < i]

    coords = []


    if method == "optimize":
        def error_function(m: np.array, selected_ts: tuple) -> float:
            if dim == 3:
                x, y, z = m
            elif dim == 2:
                x, y = m
                z = 0
            else:
                raise Exception("Dimension unsupported.")

            error = 0
            k = 0
            for i, j in t_range:
                di = euclidian_distance(x, y, z, *microphones[i].get_coord)
                dj = euclidian_distance(x, y, z, *microphones[j].get_coord)
                delta = (di - dj)

                error += abs(delta - selected_ts[k])
                k += 1

            return error / k

        # For each timeshift minimize the error for x, y, z coordinates
        min_ts = {(i, j): euclidian_distance(*microphones[i].get_coord, *microphones[j].get_coord)
                  for i in range(n) for j
                  in range(n) if j < i
                  }

        for elt in distance_shift:
            # remove impossible distance shift
            if any(map(lambda c: abs(c[0]) > min_ts[c[1]], zip(elt, t_range))):
                continue

            res = minimize(error_function, start_point, args=(elt,), method="Nelder-Mead", tol=0.001)

            if error_function(res.x, elt) < max_error:
                if dim == 3:
                    xl, yl, zl = res.x
                elif dim == 2:
                    xl, yl = res.x
                    zl = 0.0
                else:
                    raise Exception("Dimension unsupported.")

                coords.append([xl, yl, zl])

    elif method == "trilateration":
        min_ts = {(i, j): euclidian_distance(*microphones[i].get_coord, *microphones[j].get_coord)
                  for i in range(n) for j
                  in range(n) if j < i
                  }

        for elt in distance_shift:
            # remove impossible distance shift
            if any(map(lambda c: abs(c[0]) > min_ts[c[1]], zip(elt, t_range))):
                continue

            mic_time_shift = {(i, j): elt[k] for k, (i, j) in enumerate(t_range)}

            ds1 = mic_time_shift.get((0, 1), - mic_time_shift.get((1, 0), 0.0))
            ds2 = mic_time_shift.get((0, 2), - mic_time_shift.get((2, 0), 0.0))

            res = trilateration(microphones[0].get_coord[:2],
                                microphones[1].get_coord[:2],
                                microphones[2].get_coord[:2],
                                ds1,
                                ds2)
            if res is not None:
                xl, yl = res
                zl = 0.0

                coords.append([xl, yl, zl])
    else:
        raise Exception("Unsupported method.")

    # If there are no candidate
    if len(coords) == 0:
        return []

    coords = np.array(coords)

    # Clustering to find barycentre of each cluster corresponding to potential source coordinate
    result: list[tuple[float, float, float] | tuple[float, float]] = []

    clustering = MeanShift()
    clustering.fit(coords)

    labels = clustering.labels_
    cluster_centers = labels_barycenter(coords, labels)

    unique, counts = np.unique(labels, return_counts=True)
    dict_labels = dict(zip(unique, counts))

    for i, center in sorted([*cluster_centers.items()], key=lambda c: dict_labels[c[0]], reverse=True):
        if dict_labels[i] > 1:
            if dim == 3:
                xc, yc, zc = center
                result.append((xc, yc, zc))
            elif dim == 2:
                xc, yc, _ = center
                result.append((xc, yc))

    return result


def locate_source(microphones: list[Microphone],
                  records: list[np.ndarray],
                  sample_rate: int,
                  start_point: np.ndarray | None,
                  temperature: float = DEFAULT_TEMPERATURE,
                  method: str = "optimize") -> tuple[float, float, float] | tuple[float, float]:
    """
    This function tries to find the coordinate of the source.
    It first determines the time shift between all signals and then uses a minimization algorithm to find the coordinate
    of the source.
    :param microphones: List of microphones.
    :param records: List of records.
    :param sample_rate: Sampling rate of the two signals.
    :param start_point: The starting point of the search of sources
    :param temperature: Temperature of space where the mesure is realized.
    :param method: Methode to use to find coordinate. ('optimize' or 'trilateration')
    """
    assert len(records) >= 3, "records must contain at least 3 records"
    assert len(records) == len(microphones), "microphones and records must be the same length"

    n = len(records)
    sound_speed = define_sound_speed(temperature)

    mic_time_shift: dict[tuple[int, int], float] = {}

    # Get all time shifts for every microphone
    t_range = [(i, j) for j in range(n) for i in range(n) if j < i]
    for i, j in t_range:
        ts: float = signal_time_shift(records[i], records[j], rate=sample_rate, unit="s")
        mic_time_shift[(i, j)] = ts * sound_speed

    if method == "optimize":
        dim = len(start_point)

        def error_function(m: np.ndarray) -> float:
            if dim == 3:
                x, y, z = m
            elif dim == 2:
                x, y = m
                z = 0
            else:
                raise Exception("Dimension unsupported.")

            error = 0
            k = 0
            for i, j in t_range:
                di = euclidian_distance(x, y, z, *microphones[i].get_coord)
                dj = euclidian_distance(x, y, z, *microphones[j].get_coord)
                delta = (di - dj)

                error += abs(delta - mic_time_shift[(i, j)])
                k += 1

            return error / k

        # find the coordinate of the source using minimization algorithm
        res = minimize(error_function, start_point, tol=0.001, method="Nelder-Mead")

        if len(start_point) == 3:
            xl, yl, zl = res.x
            return float(xl), float(yl), float(zl)

        elif len(start_point) == 2:
            xl, yl = res.x
            return float(xl), float(yl), 0.0
        else:
            raise Exception("Dimension unsupported.")

    elif method == "trilateration":
        ds1 = mic_time_shift.get((0, 1), - mic_time_shift.get((1, 0), None))
        ds2 = mic_time_shift.get((0, 2), - mic_time_shift.get((2, 0), None))

        res = trilateration(microphones[0].get_coord[:2],
                            microphones[1].get_coord[:2],
                            microphones[2].get_coord[:2],
                            ds1,
                            ds2)

        if res is None:
            return tuple()

        else:
            return res + (0,)

    else:
        raise Exception("Method unsupported.")


def locate_many_sources_spikes(microphones: list[Microphone],
                               records: list[np.ndarray],
                               sample_rate: int,
                               n_peaks: int,
                               start_point: np.ndarray,
                               max_error: float = 1.0,
                               temperature: float = DEFAULT_TEMPERATURE,
                               method: str = "optimize"
                               ):
    """
    This function locate many sources using the spikes method.
    :param microphones: List of microphones.
    :param records: List of records.
    :param sample_rate: Sampling rate of the two signals.
    :param start_point: The starting point of the search of sources
    :param temperature: Temperature of space where the mesure is realized.
    :param method: Methode to use to find coordinate. ('optimize' or 'trilateration')
    :param n_peaks: Number of peaks to use.
    :param max_error:  Max tolerated error
    :return: A list of possible coordinates.
    """
    # Prepare data
    n = len(records)
    t_range = [(i, j) for j in range(n) for i in range(n) if j < i]

    initial_distance_shift = []

    # Get all 'n_tries' peaks in records
    for (i, j) in t_range:
        corr: np.ndarray = correlate(records[i], records[j], method="fft", mode="full")
        peaks, _ = find_peaks(corr)
        peaks: np.ndarray = peaks
        c: np.ndarray = np.argpartition(corr[peaks], -n_peaks)[-n_peaks:]
        ds = np.round(peaks[c] - len(corr) / 2) * 1 / sample_rate * define_sound_speed(temperature)

        initial_distance_shift.append(ds)

    list_distance_shift = [*product(*initial_distance_shift)]

    return possible_coordinate(microphones, list_distance_shift, start_point, max_error, method=method)


def locate_many_sources_spectrogram(microphones: list[Microphone],
                                    records: list[np.ndarray],
                                    sample_rate: int,
                                    start_point: np.ndarray,
                                    length: int = 16,
                                    max_error: float = 1.0,
                                    temperature: float = DEFAULT_TEMPERATURE,
                                    method: str = "optimize") -> list[tuple[float, float, float]]:
    """
    This function locate many sources using the spectrogram method.
    :param microphones: List of microphones.
    :param records: List of records.
    :param sample_rate: Sampling rate of the two signals.
    :param start_point: The starting point of the search of sources
    :param temperature: Temperature of space where the mesure is realized.
    :param method: Methode to use to find coordinate. ('optimize' or 'trilateration')
    :param length: Length of the spectrogram to use.
    :param max_error:  Max tolerated error
    :return: A list of possible coordinates.
    """
    n = len(records[0])
    records = np.array(records)
    pad_length = (length - (n % length)) % length
    records = np.pad(records, ((0, 0), (0, pad_length)))
    segmented_records = records.reshape(len(records), -1, length)

    spectrogram = np.fft.rfft(segmented_records, axis=2)

    indices = np.arange(length // 2 + 1)
    modified_spectrograms = np.zeros(
        (len(records), length // 2 + 1, (n // length + 1), length // 2 + 1),
        dtype=np.complex128)

    for k in range(len(records)):
        modified_spectrograms[k, indices, :, indices] = spectrogram[k, :, indices]

    reconstructed_segments = np.fft.irfft(modified_spectrograms, n=length, axis=3)
    reconstructed_signals = reconstructed_segments.transpose(1, 0, 2, 3).reshape(length // 2 + 1, len(records), -1)
    signal_list = np.swapaxes(reconstructed_signals, 0, 1)

    # get timeshift
    i_to_d = 1 / sample_rate * define_sound_speed(temperature)
    freq = np.fft.rfftfreq(length, 1 / sample_rate)

    list_distance_shift = [
        [signal_time_shift(signal_list[i][fi], signal_list[j][fi], "index") * i_to_d
         for j in range(len(records))
         for i in range(len(records)) if j < i] for fi, _ in enumerate(freq)
    ]

    return possible_coordinate(microphones, list_distance_shift, start_point, max_error, method=method)


def locate_many_sources_both(microphones: list[Microphone],
                             records: list[np.ndarray],
                             sample_rate: int,
                             n_tries: int,
                             start_point: np.ndarray,
                             length: int = 16,
                             max_error: float = 1.0,
                             temperature: float = DEFAULT_TEMPERATURE,
                             method: str = "optimize"
                             ) -> list[tuple[float, float, float] | tuple[float, float]]:
    """
    This function locate many sources using both the spectrogram and peaks method.
    :param microphones: List of microphones.
    :param records: List of records.
    :param sample_rate: Sampling rate of the two signals.
    :param start_point: The starting point of the search of sources
    :param temperature: Temperature of space where the mesure is realized.
    :param method: Methode to use to find coordinate. ('optimize' or 'trilateration')
    :param length: Length of the spectrogram to use.
    :param n_tries: Numbers of spikes to use
    :param max_error:  Max tolerated error
    :return: A list of possible coordinates.
    """
    t, freq, _ = spectrogram(records[0], sample_rate, length)
    n = len(records)
    mask = np.array([freq for _ in range(len(t))]).T

    spectrogram_list = [spectrogram(r, sample_rate, length, workers=12)[2] for r in records]

    signal_list = [
        [
            inverse_spectrogram(np.where(mask != f, 0, spectrogram_list[i]), length, workers=12) for f in freq
        ] for i in range(n)
    ]

    t_range = [(i, j) for j in range(n) for i in range(n) if j < i]

    list_distance_shift = []

    for sig1, sig2, sig3 in zip(*signal_list):

        k = 0
        sig = [sig1, sig2, sig3]

        init_ds = []

        for (i, j) in t_range:
            corr: np.ndarray = correlate(sig[i], sig[j], method="fft", mode="full")
            peaks, _ = find_peaks(corr)
            peaks: np.ndarray = peaks
            c: np.ndarray = np.argpartition(corr[peaks], -n_tries)[-n_tries:]

            ds = np.round(peaks[c] - len(corr) / 2) * 1 / sample_rate * define_sound_speed(temperature)

            init_ds.append(ds)

            k += 1

        list_distance_shift += [*product(*init_ds)]

    return possible_coordinate(microphones, list_distance_shift, start_point, max_error, method=method)


